using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using CashflowChains.Economy;
using CashflowChains.Empire;
using CashflowChains.Domain;
internal static class ServerBridge {
 public sealed class Request {public string AccountId,Command,RequestId,BusinessId,ProjectId,Template,NodeId,SourceItem,CityName,LoanId;public long TrustedNow,Amount;public int Level,Minutes,PropertyId,X,Y,CityDay,PriceBasisPoints,Staff,Budget,Quantity;public bool East,Open,Sponsorship;public Board Board;public EmpireAccount State;}
 internal static void Run(BalanceConfig config,string file){var request=JsonSerializer.Deserialize<Request>(File.ReadAllText(file),Program.Json);if(string.IsNullOrEmpty(request.AccountId)||request.TrustedNow<1)throw new ArgumentException("Missing server context");
  if(request.Command=="create"){Console.WriteLine(JsonSerializer.Serialize(new EmpireAccount{Economy=new EconomyState{AccountId=request.AccountId}},Program.Json));return;}
  if(request.State==null||request.State.Economy.AccountId!=request.AccountId)throw new ArgumentException("Wrong persisted account");var engine=new EmpireEngine(config,request.State,_=>true);
  if(request.Command=="city-investment-quote"){Console.WriteLine(JsonSerializer.Serialize(engine.QuoteCityInvestment(request.BusinessId,request.X,request.Y,request.PropertyId),Program.Json));return;}
  if(request.Command=="city-forecast"||request.Command=="city-current-day"){Console.WriteLine(JsonSerializer.Serialize(request.Command=="city-forecast"?engine.ForecastCity():engine.CurrentCityDay(),Program.Json));return;}
  if(request.Command=="development-quote"){
   var q=DevelopmentPlanning.Inspect(config,engine.Snapshot,request.BusinessId);
   string action=q.Action==DevelopmentAction.TierLimit?"tier-limit":q.Action==DevelopmentAction.BuilderBusy?"builder-busy":q.Action==DevelopmentAction.FindResources?"find-resources":q.Action.ToString().ToLowerInvariant();
   Console.WriteLine(JsonSerializer.Serialize(new{businessId=q.BusinessId,level=q.Level,nextLevel=q.NextLevel==0?(int?)null:q.NextLevel,primaryAction=action,affordable=q.Affordable,beforeHourly=q.BeforeHourly,afterHourly=q.AfterHourly,output=q.Output,seconds=q.Seconds,storage=q.Storage,requirements=q.Requirements.Select(r=>new{itemId=r.ItemId,required=r.Required,owned=r.Owned,missing=r.Missing}).ToArray()},Program.Json));return;
  }
  switch(request.Command){case "city-advance":engine.AdvanceCityTo(request.TrustedNow);break;case "city-finance":engine.FinanceCity(request.RequestId,request.Amount,request.TrustedNow);break;case "city-repay":engine.RepayCityLoan(request.RequestId,request.LoanId,request.Amount,request.TrustedNow);break;case "city-hire":engine.StaffCityBusiness(request.RequestId,request.PropertyId,request.Staff,request.TrustedNow);break;case "city-advertise":engine.MarketCityBusiness(request.RequestId,request.PropertyId,request.Budget,request.TrustedNow);break;case "city-materials":engine.BuyCityMaterials(request.RequestId,request.SourceItem,request.Quantity,request.TrustedNow);break;case "city-agreement":engine.AgreeCityPartner(request.RequestId,request.Sponsorship,request.TrustedNow);break;case "city-open":engine.OpenCity(request.TrustedNow);break;case "city-build":engine.BuildCity(request.RequestId,request.BusinessId,request.X,request.Y,request.TrustedNow);break;case "city-upgrade":engine.UpgradeCity(request.RequestId,request.PropertyId,request.TrustedNow);break;case "city-finish":engine.FinishCityBuild(request.ProjectId,request.TrustedNow);break;case "city-move":engine.MoveCityProperty(request.RequestId,request.PropertyId,request.X,request.Y,request.TrustedNow);break;case "city-price":engine.SetCityPrice(request.RequestId,request.PropertyId,request.PriceBasisPoints,request.TrustedNow);break;case "city-expand":engine.ExpandCity(request.RequestId,request.East,request.TrustedNow);break;case "city-start-day":engine.StartCityDay(request.TrustedNow);break;case "city-settle-day":engine.SettleCityDay(request.CityDay,request.TrustedNow);break;case "city-rename":engine.RenameCity(request.RequestId,request.CityName,request.TrustedNow);break;case "city-toggle":engine.SetCityOpen(request.RequestId,request.PropertyId,request.Open,request.TrustedNow);break;case "city-grid":engine.ImproveCityGrid(request.RequestId,request.TrustedNow);break;case "round":engine.RecordCertified(request.Level,request.Board,request.TrustedNow);break;case "build":engine.StartConstruction(request.RequestId,request.BusinessId,request.TrustedNow);break;case "finish":engine.FinishConstruction(request.RequestId,request.ProjectId,request.TrustedNow);break;case "collect":engine.CollectAll(request.RequestId,request.TrustedNow);break;case "dispatch":engine.StartDispatch(request.RequestId,request.Template,request.Board,request.TrustedNow);break;case "dispatch-claim":engine.ClaimDispatch(request.ProjectId,request.TrustedNow);break;case "research-start":engine.StartResearch(request.RequestId,request.NodeId,request.TrustedNow);break;case "research-finish":engine.FinishResearch(request.ProjectId,request.TrustedNow);break;case "speedup":engine.SpendSpeedup(request.RequestId,request.ProjectId,request.SourceItem,request.Minutes,request.TrustedNow);break;default:throw new ArgumentException("Unsupported command");}
  Console.WriteLine(JsonSerializer.Serialize(engine.Snapshot,Program.Json));
 }
}
